<script setup>
import { useCart } from '../cart/useCart.js'
import { formatMXN } from '~~/shared/features/pricing/prices.js'
const cart = await useCart()
const { data, error, status, refresh } = await useFetch('/api/catalog/bundles')
</script>
<template><section v-if="error || status === 'pending' || data?.bundles.length" class="mt-10" aria-label="Combos configurados"><h2 class="text-display-m font-bold">Combos de presentaciones fijas</h2><UiLoading v-if="status === 'pending'" label="Cargando combos…" :cards="2" /><div v-else-if="error"><p class="mt-3">No pudimos cargar los combos.</p><UiButton variant="secondary" @click="refresh()">Reintentar</UiButton></div><ul v-else class="mt-4 grid gap-4 md:grid-cols-2"><li v-for="bundle in data.bundles" :key="bundle.id" class="rounded-sm border border-line bg-surface p-4"><h3 class="font-semibold">{{ bundle.name }}</h3><p v-if="bundle.description" class="mt-2">{{ bundle.description }}</p><ul class="mt-3 text-body-s"><li v-for="component in bundle.components" :key="component.variantId"><NuxtLink :to="{ path: `/producto/${component.productId}`, query: { variante: component.variantId } }" class="underline">{{ component.quantity }} × {{ component.name }} · {{ component.presentation }} · SKU {{ component.sku }}</NuxtLink></li></ul><p class="mt-4 font-mono font-semibold">{{ formatMXN(bundle.priceCents) }}</p><p v-if="bundle.savingCents !== '0'" class="mt-2 text-body-s">Ahorro frente a compra individual: {{ formatMXN(bundle.savingCents) }}</p><p v-if="bundle.servings" class="mt-2 text-body-s">{{ bundle.servings }} porciones sumadas de sus componentes</p><p v-else class="mt-2 text-body-s">Porciones no documentadas para todos los componentes.</p><p class="mt-2 text-body-s">{{ bundle.availableQty ? `${bundle.availableQty} combos disponibles` : 'Combo agotado' }}</p><UiButton class="mt-4" :disabled="cart.busy.value || !bundle.availableQty" @click="cart.addBundle(bundle.id)">Agregar combo</UiButton></li></ul></section></template>
